gMy(){return"\u0986\u09aa\u09a8\u09be\u09b0 \u09b9\u09be\u09a4\u09c7 \u09a5\u09be\u0995\u09be \u09a8\u0997\u09a6, \u0996\u09b0\u099a, \u098f\u09ac\u0982 \u09b9\u09b8\u09cd\u09a4\u09be\u09a8\u09cd\u09a4\u09b0"},
gML(){return"\u0985\u09b0\u09cd\u09a5\u09ac\u099b\u09b0"},
gMK(){return"\u098f\u0995\u099f\u09bf \u09ac\u099b\u09b0\u09c7\u09b0 \u09b9\u09bf\u09b8\u09be\u09ac \u09ac\u09a8\u09cd\u09a7 \u09ac\u09be \u09aa\u09c1\u09a8\u09b0\u09be\u09af\u09bc \u0996\u09c1\u09b2\u09c1\u09a8"},
gMJ(){return"\u0996\u09b0\u099a\u09c7\u09b0 \u09ac\u09bf\u09ad\u09be\u0997"},
gMI(){return"\u09b8\u09ae\u09cd\u09aa\u09be\u09a6\u09a8\u09be\u09af\u09cb\u0997\u09cd\u09af, \u09a6\u09b2\u09ac\u09a6\u09cd\u09a7\u09af\u09cb\u0997\u09cd\u09af \u2014 \u09af\u09c7\u09ae\u09a8 \u09af\u09be\u09a8\u09ac\u09be\u09b9\u09a8 \u0996\u09b0\u099a > \u09af\u09be\u09a8\u09ac\u09be\u09b9\u09a8 \u09e7 > \u09aa\u09c7\u099f\u09cd\u09b0\u09cb\u09b2"},
gMZ(){return"\u09ac\u09bf\u0995\u09cd\u09b0\u09af\u09bc\u0995\u09b0\u09cd\u09ae\u09c0 \u09aa\u09b0\u09bf\u099a\u09af\u09bc \u09aa\u09b0\u09cd\u09af\u09be\u09b2\u09cb\u099a\u09a8\u09be"},
gMY(){return"\u0997\u09cd\u09b0\u09be\u09b9\u0995, \u099a\u09be\u09b2\u09be\u09a8, \u098f\u09ac\u0982 \u0995\u09ae\u09bf\u09b6\u09a8 \u09b0\u09c7\u099f\u09c7\u09b0 \u09aa\u09c1\u09b0\u09a8\u09cb \u09ac\u09bf\u0995\u09cd\u09b0\u09af\u09bc\u0995\u09b0\u09cd\u09ae\u09c0\u09b0 \u09a8\u09be\u09ae \u098f\u0995\u099f\u09bf \u09aa\u09cd\u09b0\u0995\u09c3\u09a4 \u0995\u09b0\u09cd\u09ae\u09c0 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f\u09c7\u09b0 \u09b8\u09be\u09a5\u09c7 \u09b8\u0982\u09af\u09c1\u0995\u09cd\u09a4 \u0995\u09b0\u09c1\u09a8"},
gRH(){return"\u098f\u0987 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u099f\u09bf \u09ab\u09bf\u0999\u09cd\u0997\u09be\u09b0\u09aa\u09cd\u09b0\u09bf\u09a8\u09cd\u099f \u09ac\u09be \u09ab\u09c7\u09b8 \u0986\u09a8\u09b2\u0995 \u09b8\u09ae\u09b0\u09cd\u09a5\u09a8 \u0995\u09b0\u09c7 \u09a8\u09be\u0964"},
gRE(){return"\u09ab\u09bf\u0999\u09cd\u0997\u09be\u09b0\u09aa\u09cd\u09b0\u09bf\u09a8\u09cd\u099f / \u09ab\u09c7\u09b8 \u0986\u09a8\u09b2\u0995"},
gRD(){return"\u098f\u0987 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u09aa\u09bf\u09a8 \u099f\u09be\u0987\u09aa \u0995\u09b0\u09be \u098f\u09a1\u09bc\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u09a8 \u2014 \u09af\u0996\u09a8\u0987 \u098f\u099f\u09bf \u09a8\u09bf\u09b6\u09cd\u099a\u09bf\u09a4 \u0995\u09b0\u09a4\u09c7 \u09a8\u09be \u09aa\u09be\u09b0\u09c7 \u09af\u09c7 \u098f\u099f\u09bf \u0986\u09aa\u09a8\u09bf, \u09a4\u0996\u09a8 \u098f\u099f\u09bf \u0986\u09aa\u09a8\u09be\u09b0 \u09aa\u09bf\u09a8\u09c7 \u09ab\u09bf\u09b0\u09c7 \u09af\u09be\u09af\u09bc\u0964"},
gRF(){return"\u09ab\u09bf\u0999\u09cd\u0997\u09be\u09b0\u09aa\u09cd\u09b0\u09bf\u09a8\u09cd\u099f / \u09ab\u09c7\u09b8 \u0986\u09a8\u09b2\u0995 \u099a\u09be\u09b2\u09c1 \u0995\u09b0\u09a4\u09c7 \u09a8\u09bf\u09b6\u09cd\u099a\u09bf\u09a4 \u0995\u09b0\u09c1\u09a8"},
gSW(){return"\u0995\u09cb\u09ae\u09cd\u09aa\u09be\u09a8\u09bf / \u09a6\u09cb\u0995\u09be\u09a8\u09c7\u09b0 \u09a8\u09be\u09ae *"},
gSV(){return"\u09aa\u09cd\u09b0\u09af\u09bc\u09cb\u099c\u09a8\u09c0\u09af\u09bc \u2014 \u0986\u09aa\u09a8\u09be\u09b0 \u09a4\u09c8\u09b0\u09bf \u0995\u09b0\u09be \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u09a8\u09a5\u09bf\u09a4\u09c7 \u09aa\u09cd\u09b0\u09bf\u09a8\u09cd\u099f \u09b9\u09af\u09bc"},
gT5(){return"\u099f\u09cd\u09af\u09be\u0997\u09b2\u09be\u0987\u09a8 (\u0990\u099a\u09cd\u099b\u09bf\u0995)"},
gT4(){return'\u09a8\u09a5\u09bf\u09a4\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u09a8\u09be\u09ae\u09c7\u09b0 \u09a8\u09bf\u099a\u09c7 \u09ae\u09c1\u09a6\u09cd\u09b0\u09bf\u09a4 \u098f\u0995\u099f\u09bf \u099b\u09cb\u099f \u09b2\u09be\u0987\u09a8, \u09af\u09c7\u09ae\u09a8 "FOR TRADING"'},
