gT1(){return"\u09b8\u09c1\u0987\u09ab\u099f \u0995\u09cb\u09a1"},
gSS(){return"\u09ab\u09be\u0993\u09b0\u09be\u09a8 \u09ac\u09bf\u09ac\u09b0\u09a3 (\u0990\u099a\u09cd\u099b\u09bf\u0995)"},
gSR(){return"\u09a4\u09be\u09ce\u0995\u09cd\u09b7\u09a3\u09bf\u0995 \u09b8\u09cd\u09a5\u09be\u09a8\u09be\u09a8\u09cd\u09a4\u09b0\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u0986\u09aa\u09a8\u09be\u09b0 \u09ab\u09be\u0993\u09b0\u09be\u09a8 \u0986\u0987\u09a1\u09bf / QR \u09b0\u09c7\u09ab\u09be\u09b0\u09c7\u09a8\u09cd\u09b8"},
gSO(){return"\u09a8\u09a5\u09bf\u09b0 \u09ab\u09a8\u09cd\u099f"},
gGO(){return"\u09a8\u09a5\u09bf\u09b0 \u0989\u099a\u09cd\u099a\u09be\u09b0\u09a3 \u09b0\u0999"},
gGQ(){return"\u099f\u09cd\u09af\u09be\u0997\u09b2\u09be\u0987\u09a8 \u09b0\u0999"},
gT3(){return"\u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u09a8\u09a5\u09bf\u09a4\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u09a8\u09be\u09ae\u09c7\u09b0 \u09a8\u09bf\u099a\u09c7 \u09ae\u09c1\u09a6\u09cd\u09b0\u09bf\u09a4"},
gT2(){return"\u0986\u09aa\u09a8\u09be\u09b0 \u09ae\u09c1\u09a6\u09cd\u09b0\u09bf\u09a4 \u09a8\u09a5\u09bf\u09a4\u09c7 \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u099f\u09c7\u09ac\u09bf\u09b2/\u09ac\u0995\u09cd\u09b8 \u09ac\u09b0\u09cd\u09a1\u09be\u09b0\u09c7\u09b0 \u099c\u09a8\u09cd\u09af\u0993 \u09ac\u09cd\u09af\u09ac\u09b9\u09c3\u09a4 \u09b9\u09af\u09bc \u2014 \u09aa\u09cd\u09b0\u09bf\u09a8\u09cd\u099f \u09b2\u09c7\u0986\u0989\u099f \u09a8\u09bf\u099c\u09c7\u0987 \u0995\u0996\u09a8\u0993 \u09aa\u09b0\u09bf\u09ac\u09b0\u09cd\u09a4\u09a8 \u09b9\u09af\u09bc \u09a8\u09be, \u09b6\u09c1\u09a7\u09c1 \u098f\u0987 \u098f\u0995\u099f\u09bf \u09b0\u0999\u0964"},
gGR(){return"\u09a8\u09a5\u09bf\u09b0 \u099f\u09c7\u0995\u09cd\u09b8\u099f \u09b0\u0999"},
gT6(){return"\u0986\u0987\u099f\u09c7\u09ae\u09c7\u09b0 \u09ac\u09bf\u09ac\u09b0\u09a3, \u09a0\u09bf\u0995\u09be\u09a8\u09be, \u09aa\u09b0\u09bf\u09ae\u09be\u09a3 \u098f\u09ac\u0982 \u0985\u09a8\u09cd\u09af\u09be\u09a8\u09cd\u09af \u09ae\u09c2\u09b2 \u099f\u09c7\u0995\u09cd\u09b8\u099f"},
gSX(){return"\u0995\u09cb\u09ae\u09cd\u09aa\u09be\u09a8\u09bf / \u09a6\u09cb\u0995\u09be\u09a8\u09c7\u09b0 \u09a8\u09be\u09ae \u0986\u09ac\u09b6\u09cd\u09af\u0995\u0964"},
gSK(){return"\u0986\u09aa\u09a8\u09be\u09b0 \u0995\u09cb\u09ae\u09cd\u09aa\u09be\u09a8\u09bf\u09b0 \u09b2\u09cb\u0997\u09cb \u09a8\u09bf\u09b0\u09cd\u09ac\u09be\u099a\u09a8 \u0995\u09b0\u09c1\u09a8"},
gSs(){return"\u098f\u0987 \u09b0\u0999\u099f\u09bf \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09c1\u09a8"},
gNp(){return"\u0995\u09cd\u09b2\u09be\u0989\u09a1 \u099f\u09bf\u09ae \u2014 \u09b8\u09a6\u09b8\u09cd\u09af \u09a6\u09c7\u0996\u09c1\u09a8 \u09ac\u09be \u09b8\u09b0\u09be\u09a8"},
gNu(){return"\u0987\u09ae\u09c7\u0987\u09b2\u09c7\u09b0 \u09ae\u09be\u09a7\u09cd\u09af\u09ae\u09c7 \u098f\u0995\u099c\u09a8 \u0995\u09b0\u09cd\u09ae\u099a\u09be\u09b0\u09c0\u0995\u09c7 \u0986\u09ae\u09a8\u09cd\u09a4\u09cd\u09b0\u09a3 \u099c\u09be\u09a8\u09be\u09a8"},
NC(a){return a+" \u09b8\u09b0\u09be\u09ac\u09c7\u09a8?"},
gNB(){return"\u09a4\u09be\u09b0\u09be \u0986\u09b0 \u098f\u0987 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7 \u09b8\u09be\u0987\u09a8 \u0987\u09a8 \u0995\u09b0\u09a4\u09c7 \u09aa\u09be\u09b0\u09ac\u09c7 \u09a8\u09be\u0964 \u09a4\u09be\u09b0\u09be \u09af\u09be \u0995\u09bf\u099b\u09c1 \u09a4\u09c8\u09b0\u09bf \u0995\u09b0\u09c7\u099b\u09c7 \u09ac\u09be \u09a4\u09be\u09a6\u09c7\u09b0 \u09af\u09be \u09ac\u09b0\u09be\u09a6\u09cd\u09a6 \u0995\u09b0\u09be \u09b9\u09af\u09bc\u09c7\u099b\u09c7 \u2014 \u099a\u09be\u09b2\u09be\u09a8, \u09a1\u09c7\u09b2\u09bf\u09ad\u09be\u09b0\u09bf, \u09b2\u09c7\u099c\u09be\u09b0 \u098f\u09a8\u09cd\u099f\u09cd\u09b0\u09bf \u2014 \u09b8\u09ac\u0995\u09bf\u099b\u09c1 \u09a0\u09bf\u0995 \u09af\u09c7\u09ae\u09a8 \u0986\u099b\u09c7, \u09a4\u09be\u09a6\u09c7\u09b0 \u09b8\u09a0\u09bf\u0995\u09ad\u09be\u09ac\u09c7 \u09a6\u09be\u09af\u09bc\u09c0 \u0995\u09b0\u09c7 \u09a5\u09be\u0995\u09ac\u09c7\u0964 \u098f\u099f\u09bf \u098f\u0996\u09be\u09a8 \u09a5\u09c7\u0995\u09c7 \u09aa\u09c2\u09b0\u09cd\u09ac\u09be\u09ac\u09b8\u09cd\u09a5\u09be\u09af\u09bc \u09ab\u09c7\u09b0\u09be\u09a8\u09cb \u09af\u09be\u09ac\u09c7 \u09a8\u09be; \u09a4\u09be\u09b0\u09be \u09ab\u09bf\u09b0\u09c7 \u098f\u09b2\u09c7 \u09a4\u09be\u09a6\u09c7\u09b0 \u098f\u0995\u099f\u09bf \u09a8\u09a4\u09c1\u09a8 \u09a6\u09b2\u09c7\u09b0 \u09b8\u09a6\u09b8\u09cd\u09af \u09b9\u09bf\u09b8\u09be\u09ac\u09c7 \u09aa\u09c1\u09a8\u09b0\u09be\u09af\u09bc \u09af\u09cb\u0997 \u0995\u09b0\u09a4\u09c7 \u09ac\u09b2\u09c1\u09a8\u0964"},
NE(a){return a+" \u09b8\u09b0\u09be\u09a8\u09cb \u09b9\u09af\u09bc\u09c7\u099b\u09c7\u0964"},
ND(a,b){return a+" \u09b8\u09b0\u09be\u09a8\u09cb \u09af\u09be\u09af\u09bc\u09a8\u09bf: "+b},
gES(){return"\u09b8\u09b0\u09be\u09a8"},
gNv(){return"\u0995\u09cb\u09a8\u09cb \u09ab\u09cb\u09a8 \u09a8\u09c7\u0987"},
